import XCTest
@testable import OneSatColor

/// Golden strings generated by running `@bopen-io/color-permission-module` 0.2.2 (the version
/// `@1sat/actions` pins) under Node: identifiers, plan labels and the receipt JSON must match it
/// byte for byte, or a TS wallet on the same storage account cannot read what Swift files.
final class ColorIdentifierGoldenTests: XCTestCase {
    let asset = try! ColorAssetID("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab_7")
    let prefix = "cHJlZml4MTIzNDU2Nzg5MA=="
    let suffix = "c3VmZml4/+9876543210w=="
    let g = "0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798"

    func test_protocolNamesBasketsTopicsAndTagsMatchTS() throws {
        XCTAssertEqual(try ColorIdentifiers.protocolName(.issue, derivationPrefix: prefix, derivationSuffix: suffix), "p color issue 63484a6c5a6d6c344d54497a4e4455324e7a67354d413d3d 6333566d5a6d6c342f2b39383736353433323130773d3d")
        XCTAssertEqual(try ColorIdentifiers.protocolName(.asset(asset), derivationPrefix: prefix, derivationSuffix: suffix), "p color aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaabv7 63484a6c5a6d6c344d54497a4e4455324e7a67354d413d3d 6333566d5a6d6c342f2b39383736353433323130773d3d")
        XCTAssertEqual(try ColorIdentifiers.protocolName(.asset(asset), derivationPrefix: "\u{e9}\u{2713}", derivationSuffix: "\u{1d11e}x"), "p color aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaabv7 c3a9e29c93 f09d849e78")
        XCTAssertEqual(ColorIdentifiers.basket(asset, role: .value), "p color aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaabv7")
        XCTAssertEqual(ColorIdentifiers.basket(asset, role: .authority), "p color aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaabv7 authority")
        XCTAssertEqual(ColorIdentifiers.topic(asset), "tm_color_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab_7")
        XCTAssertEqual(ColorIdentifiers.tag(.asset(asset)), "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaabv7")
        XCTAssertEqual(ColorIdentifiers.derivationSuffixTag(suffix), "p color fbb32fdf356e062f5f84e8436c8209fddecdf45a43607e12db132a543d36783c")
        XCTAssertTrue(ColorIdentifiers.isDerivationSuffixTag(ColorIdentifiers.derivationSuffixTag(suffix)))
    }

    func test_protocolNamesParseBack() throws {
        let parsed = try ColorIdentifiers.parseProtocolName("p color aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaabv7 c3a9e29c93 f09d849e78")
        XCTAssertEqual(parsed.selector, .asset(asset))
        XCTAssertEqual(parsed.derivationPrefix, "\u{e9}\u{2713}")
        XCTAssertEqual(parsed.derivationSuffix, "\u{1d11e}x")
        XCTAssertEqual(try ColorIdentifiers.parseProtocolName("p color issue 63484a6c5a6d6c344d54497a4e4455324e7a67354d413d3d 6333566d5a6d6c342f2b39383736353433323130773d3d").selector, .issue)
        // Lone-surrogate bytes are not strict UTF-8.
        XCTAssertThrowsError(try ColorIdentifiers.parseProtocolName("p color issue eda080 61"))
        XCTAssertThrowsError(try ColorIdentifiers.parseProtocolName("p color issue 6120 61"))
    }

    func test_basketsParse() throws {
        XCTAssertEqual(try ColorIdentifiers.parseBasket("p color aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaabv7 authority")?.role, .authority)
        XCTAssertEqual(try ColorIdentifiers.parseBasket("p color aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaabv7")?.assetID, asset)
        XCTAssertNil(try ColorIdentifiers.parseBasket("p color assets"))
        XCTAssertNil(try ColorIdentifiers.parseBasket("p color aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaabv7 other"))
        XCTAssertNil(try ColorIdentifiers.parseBasket("default"))
        XCTAssertThrowsError(try ColorIdentifiers.parseBasket("p color issue"))
        XCTAssertEqual(try ColorIdentifiers.parseBalanceSelector("p color balance aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaabv7 authority")?.role, .authority)
    }

    func test_assetIDsAreCanonical() {
        for bad in ["aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab_01", "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab_4294967296", "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA_0", "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa_0", "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa_", "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.0"] {
            XCTAssertThrowsError(try ColorAssetID(bad), bad)
        }
        XCTAssertEqual(try ColorAssetID("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa_4294967295").vout, UInt32.max)
    }

    func test_remittanceStringsRefuseWhitespace() {
        for bad in ["", "a b", "a\u{a0}", "a\u{feff}", "a\u{2028}"] {
            XCTAssertThrowsError(try ColorIdentifiers.protocolName(.issue, derivationPrefix: bad, derivationSuffix: "x"))
        }
        let long = String(repeating: "x", count: 100)
        XCTAssertThrowsError(try ColorIdentifiers.protocolName(.issue, derivationPrefix: long, derivationSuffix: long))
    }

    // MARK: - Plans

    func deployPlan() -> ColorPlan {
        ColorPlan(assets: [.issue],
            ownedOutputs: [.init(outputIndex: 0, asset: .issue, derivationPrefix: prefix, derivationSuffix: suffix, senderIdentityKey: g)],
            operations: [.init(asset: .issue, operation: .deployFixed)])
    }

    func test_deployAndSendPlanLabelsMatchTS() throws {
        XCTAssertEqual(try deployPlan().labels(), [
            "p color plan 0 4 7b2276657273696f6e223a312c22617373657473223a5b224953535545225d2c226f776e65644f757470757473223a5b7b226f7574707574496e646578223a302c2261737365744964223a224953535545222c2264657269766174696f6e507265666978",
            "p color plan 1 4 223a2263484a6c5a6d6c344d54497a4e4455324e7a67354d413d3d222c2264657269766174696f6e537566666978223a226333566d5a6d6c342f2b39383736353433323130773d3d222c2273656e6465724964656e746974794b6579223a223032373962",
            "p color plan 2 4 65363637656639646362626163353561303632393563653837306230373032396266636462326463653238643935396632383135623136663831373938227d5d2c226f7065726174696f6e73223a5b7b2261737365744964223a224953535545222c226f",
            "p color plan 3 4 7065726174696f6e223a226465706c6f792d6669786564227d5d2c22696e707574506f736974696f6e73223a5b5d2c226368616e6765506f736974696f6e73223a5b5d2c22736967686173685479706573223a5b5d7d",
        ])
        let send = ColorPlan(assets: [.asset(asset)], operations: [.init(asset: .asset(asset), operation: .transfer)])
        XCTAssertEqual(try send.labels(), [
            "p color plan 0 3 7b2276657273696f6e223a312c22617373657473223a5b22616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161625f37225d2c226f776e65644f",
            "p color plan 1 3 757470757473223a5b5d2c226f7065726174696f6e73223a5b7b2261737365744964223a22616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161",
            "p color plan 2 3 625f37222c226f7065726174696f6e223a227472616e73666572227d5d2c22696e707574506f736974696f6e73223a5b5d2c226368616e6765506f736974696f6e73223a5b5d2c22736967686173685479706573223a5b5d7d",
        ])
    }

    func test_aFullPlanRoundTripsThroughLabels() throws {
        let outpoint = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab.3"
        let plan = ColorPlan(assets: [.asset(asset)],
            ownedOutputs: [.init(outputIndex: 1, asset: .asset(asset), derivationPrefix: "a\"b\\c", derivationSuffix: suffix, senderIdentityKey: g)],
            operations: [.init(asset: .asset(asset), operation: .transfer)],
            inputPositions: [.init(outpoint: outpoint, index: 0)],
            changePositions: [.init(asset: asset, index: 1), .init(asset: nil, index: 2)],
            sighashTypes: [.init(outpoint: outpoint, sighashType: 0xc3)])
        let labels = try plan.labels()
        XCTAssertEqual(labels, [
            "p color plan 0 9 7b2276657273696f6e223a312c22617373657473223a5b22616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161625f37225d2c226f776e65644f",
            "p color plan 1 9 757470757473223a5b7b226f7574707574496e646578223a312c2261737365744964223a22616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161",
            "p color plan 2 9 625f37222c2264657269766174696f6e507265666978223a22615c22625c5c63222c2264657269766174696f6e537566666978223a226333566d5a6d6c342f2b39383736353433323130773d3d222c2273656e6465724964656e746974794b6579223a22",
            "p color plan 3 9 303237396265363637656639646362626163353561303632393563653837306230373032396266636462326463653238643935396632383135623136663831373938227d5d2c226f7065726174696f6e73223a5b7b2261737365744964223a2261616161",
            "p color plan 4 9 6161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161625f37222c226f7065726174696f6e223a227472616e73666572227d5d2c22696e707574506f736974",
            "p color plan 5 9 696f6e73223a5b7b226f7574706f696e74223a22616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161622e33222c22696e646578223a307d5d2c",
            "p color plan 6 9 226368616e6765506f736974696f6e73223a5b7b2261737365744964223a22616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161625f37222c22",
            "p color plan 7 9 696e646578223a317d2c7b2261737365744964223a6e756c6c2c22696e646578223a327d5d2c22736967686173685479706573223a5b7b226f7574706f696e74223a22616161616161616161616161616161616161616161616161616161616161616161",
            "p color plan 8 9 616161616161616161616161616161616161616161616161616161616161622e33222c227369676861736854797065223a3139357d5d7d",
        ])
        let back = try XCTUnwrap(ColorPlan.fromLabels(labels.reversed() + ["unrelated"]))
        XCTAssertEqual(back.json.serialized, "{\"version\":1,\"assets\":[\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab_7\"],\"ownedOutputs\":[{\"outputIndex\":1,\"assetId\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab_7\",\"derivationPrefix\":\"a\\\"b\\\\c\",\"derivationSuffix\":\"c3VmZml4/+9876543210w==\",\"senderIdentityKey\":\"0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798\"}],\"operations\":[{\"assetId\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab_7\",\"operation\":\"transfer\"}],\"inputPositions\":[{\"outpoint\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab.3\",\"index\":0}],\"changePositions\":[{\"assetId\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab_7\",\"index\":1},{\"assetId\":null,\"index\":2}],\"sighashTypes\":[{\"outpoint\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab.3\",\"sighashType\":195}]}")
    }

    func test_badPlanLabelsAreRefused() {
        let send = [
            "p color plan 0 3 7b2276657273696f6e223a312c22617373657473223a5b22616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161625f37225d2c226f776e65644f",
            "p color plan 1 3 757470757473223a5b5d2c226f7065726174696f6e73223a5b7b2261737365744964223a22616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161616161",
            "p color plan 2 3 625f37222c226f7065726174696f6e223a227472616e73666572227d5d2c22696e707574506f736974696f6e73223a5b5d2c226368616e6765506f736974696f6e73223a5b5d2c22736967686173685479706573223a5b5d7d",
        ]
        for labels in [["p color plan 0 1 7b"], ["p color plan 0 2 " + String(repeating: "00", count: 100)],
                       ["p color plan 01 1 7b7d"], [send[0], send[0]], Array(send.dropLast()),
                       ["p color plan 0 1 7B7D"], ["p color plan 0 1 7b7d"]] {
            XCTAssertThrowsError(try ColorPlan.fromLabels(labels), "\(labels)")
        }
        XCTAssertNil(try ColorPlan.fromLabels(["p nosend expiry seconds 1"]))
    }

    func test_planValidationMatchesTheModule() {
        var twoDeploys = deployPlan()
        twoDeploys.operations.append(.init(asset: .issue, operation: .deployAuthority))
        XCTAssertThrowsError(try twoDeploys.labels())
        var outside = deployPlan()
        outside.operations = [.init(asset: .asset(asset), operation: .transfer)]
        XCTAssertThrowsError(try outside.labels())
        var badKey = deployPlan()
        badKey.ownedOutputs[0].senderIdentityKey = "02" + String(repeating: "0", count: 64)
        XCTAssertThrowsError(try badKey.labels())
    }

    // MARK: - Receipts

    func test_receiptJSONMatchesTSAndOnlyThatStringParses() throws {
        let receipt = try ColorReceipt(assetID: asset, derivationPrefix: prefix, derivationSuffix: suffix, senderIdentityKey: g)
        XCTAssertEqual(receipt.customInstructions, "{\"version\":1,\"assetId\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaab_7\",\"derivationPrefix\":\"cHJlZml4MTIzNDU2Nzg5MA==\",\"derivationSuffix\":\"c3VmZml4/+9876543210w==\",\"senderIdentityKey\":\"0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798\"}")
        XCTAssertEqual(try ColorReceipt(customInstructions: receipt.customInstructions), receipt)
        let exact = receipt.customInstructions
        for bad in [exact.replacingOccurrences(of: ",", with: ", "),
                    exact.replacingOccurrences(of: "{\"version\":1,", with: "{\"version\":1,\"x\":1,"),
                    exact.replacingOccurrences(of: "\"version\":1", with: "\"version\":1.0"),
                    exact.replacingOccurrences(of: asset.description, with: "ISSUE"),
                    "[]", "nope"] {
            XCTAssertThrowsError(try ColorReceipt(customInstructions: bad), bad)
        }
    }
}
